      if inv.at(cur) == '.' then
        key = inv.at(cur + 1)
        cur = cur + 2
      else
        local kVal, nxt = inv.expr(cur + 1, depth + 1)
        if inv.at(nxt) ~= ']' then
          return nil, nxt
        end
        key = kVal
        cur = nxt + 1
      end
      if type(value) == 'table' and (type(key) == 'string' or type(key) == 'number') then
        local v = value[key]
        value = (v ~= U.null) and v or nil
      else
        value = nil
      end
    end

    if inv.at(cur) == '(' then
      local level, p = 1, cur + 1
