    local combined = ''
    for _, s in ipairs(report.scripts) do
      if s.language == 'Lua' and type(s.text) == 'string' then
        combined = combined .. s.text
      end
    end
    if #combined > 0 then
      sourceSha = sha256(combined)
    end
  end

