    version = '0.1',
    suite_version = suiteVersion,
    source = {
      name = srcName,
      sha256 = sourceSha
    },
    runtime_report_sha256 = reportSha,
    association = 'in-memory table analysis; Cheat Engine runtime capture',
    observations = observations,
    diagnostics = diagnostics,
    limitations = limitations
  }

  return report
end

return M

end
factories['moduledump'] = function(require, api)
-- Explicit user action only. Never called by passive report capture.
local U=require('util')
