      and prev~='goto' then
      local key=nextValue=='=' and (tableDepth>0 or prev==',')
      local attribute=prev=='<' and nextValue=='>' and (name=='const' or name=='close')
      if not key and not attribute then
        local provides=(nextValue=='=' and value(i+2)~='nil')
          or (prev=='function' and nextValue=='(')
        report.dependencies[#report.dependencies+1]={
          script_id=script.id,line=t.line,section=section,name=name,kind='lua_global',
          command=provides and 'lua_global_assignment' or 'lua_global_reference',
          relation=provides and 'provides' or 'requires',
          source='lua_lexical',status='unverified'
        }
      end
    end
  end
end


function M.lines(source)
  local out,lua,block,cblock=U.array(),false,false,false
  local opaque,depth=false,0
  local n=0
  local luaState={}

  for raw in (source..'\n'):gmatch('(.-)\n') do
    n=n+1
    local trimmed=U.trim(raw):lower()

    if not lua and not block and not cblock and not luaState.close and not luaState.quote and (trimmed=='{$lua}' or trimmed:match('^{%$luacode%f[%W]')) then
      lua=true
      opaque=trimmed~='{$lua}' or depth>0
      out[#out+1]={line=n,text='',directive=opaque and 'opaque' or 'lua',note='OPAQUE-SOURCE'}

    elseif lua and not luaState.close and not luaState.quote and trimmed=='{$asm}' then
      lua=false;opaque=false
      out[#out+1]={line=n,text='',directive='asm'}

    elseif lua and not opaque and not luaState.close and not luaState.quote
      and (trimmed=='[enable]' or trimmed=='[disable]') then
      out[#out+1]={line=n,text=trimmed:upper(),luaSection=true}

    elseif lua then
      if opaque and not luaState.close and not luaState.quote and (trimmed=='[enable]' or trimmed=='[disable]') then
        out[#out+1]={line=n,text='',directive='opaque',note='SECTION-INDETERMINATE'}
      end
      maskLua(raw,luaState)
      out[#out+1]={line=n,text='',lua=not opaque and raw or nil}

    else
      local clean,quote,i='',nil,1

      while i<=#raw do
        local c=raw:sub(i,i)
        local pair=raw:sub(i,i+1)

        if block then
          if c=='}' then
            block=false
          end

        elseif cblock then
          if pair=='*/' then
            cblock=false
            i=i+1
          end

        elseif quote then
          clean=clean..c
          if c==quote then
            quote=nil
          end

        elseif c=='"' or c=="'" then
          quote=c
          clean=clean..c

        elseif pair=='//' then
          break

        elseif pair=='/*' then
          cblock=true
          i=i+1

        elseif c=='{' then
          if raw:sub(i,i+1)=='{$' then
            local finish=raw:find('}',i+2,true)
            if not finish then clean=clean..raw:sub(i);break end
            clean=clean..raw:sub(i,finish);i=finish
          else block=true end

        else
          clean=clean..c
        end

        i=i+1
      end

      clean=U.trim(clean)
      -- Only scan directives outside AA comments/strings. A mixed directive line
      -- is wholly opaque; its prefix is deliberately not interpreted as AA.
      local directives={}
      local q,j=nil,1
      while j<=#clean do
        local c=clean:sub(j,j)
        if q then if c==q then q=nil end;j=j+1
        elseif c=='"' or c=="'" then q=c;j=j+1
        elseif clean:sub(j,j+1)=='{$' then
          local name=clean:sub(j+2):match('^(%w+)')
          if name then directives[#directives+1]={name=name:lower(),pos=j} end
          local finish=clean:find('}',j+2,true)
          if not finish then break end
          j=finish+1
        elseif clean:sub(j,j+7):lower()=='[enable]' or clean:sub(j,j+8):lower()=='[disable]' then
          directives[#directives+1]={name='section_header',pos=j};j=j+1
        else j=j+1 end
      end
      local handled=false
      for _,d in ipairs(directives) do
        if d.name=='luacode' or d.name=='lua' then
          lua=true
          opaque=d.name=='luacode' or depth>0 or clean:lower()~='{$lua}'
          out[#out+1]={line=n,text='',directive=opaque and 'opaque' or 'lua',note='OPAQUE-SOURCE'}
          handled=true;break
        elseif d.name=='ifdef' or d.name=='ifndef' then
          depth=depth+1;handled=true
          out[#out+1]={line=n,text='',directive='opaque',note='CONDITIONAL-SOURCE'}
        elseif d.name=='section_header' and depth>0 then
          out[#out+1]={line=n,text='',directive='opaque',note='SECTION-INDETERMINATE'}
          handled=true
        elseif d.name=='endif' then
          out[#out+1]={line=n,text='',directive='opaque',note=depth==0 and 'CONDITIONAL-UNMATCHED' or 'CONDITIONAL-SOURCE'}
          depth=math.max(0,depth-1);handled=true
        end
      end
      if not handled then
        if depth>0 then
          if clean:lower()=='[enable]' or clean:lower()=='[disable]' then
            out[#out+1]={line=n,text='',directive='opaque',note='SECTION-INDETERMINATE'}
          else out[#out+1]={line=n,text=''} end
        else out[#out+1]={line=n,text=clean} end
      end
    end
  end

  if depth>0 or (lua and opaque) then
    out[#out+1]={line=n,text='',directive='opaque',note='OPAQUE-INCOMPLETE'}
  end
  return out
end

local function parseByteArray(text)
  if type(text)~='string' then
    return nil
  end

  local body=text:match('^%s*{%s*(.-)%s*}%s*$')

  if not body then
    return nil
  end

  local bytes=U.array()

  for token in body:gmatch('[^,]+') do
    token=U.trim(token)

    local hex=token:match('^0[xX]([%x]+)$')
    local dec=token:match('^(%d+)$')
    local value

    if hex then
      value=tonumber(hex,16)
    elseif dec then
      value=tonumber(dec,10)
    else
      return nil
    end

    if not value or value<0 or value>255 then
      return nil
    end

    bytes[#bytes+1]=value
  end

  if #bytes==0 then
    return nil
  end

  return bytes
end

local function inspectLuaHook(text,script,report,line,section)
  if type(text)~='string' then
    return
  end

  local module=text:match(
    "local%s+base%s*=%s*getAddress%s*%(%s*['\"]([^'\"]+)['\"]%s*%)"
  )

  local rvaHex=text:match(
    'local%s+source%s*=%s*base%s*%+%s*0[xX]([%x]+)'
  )

  local rvaDec=text:match(
    'local%s+source%s*=%s*base%s*%+%s*(%d+)'
  )

  if not module or not rvaHex and not rvaDec then
    return
  end

  local rva

  if rvaHex then
    rva=tonumber(rvaHex,16)
  else
    rva=tonumber(rvaDec,10)
  end

  if not rva then
    return
  end

  local expectedText=text:match(
    'local%s+expected%s*=%s*({.-})'
  )

  local originalText=text:match(
    'local%s+original%s*=%s*({.-})'
  )

  local expected=parseByteArray(expectedText)
  local original=parseByteArray(originalText)

  report.resources[#report.resources+1]={
    script_id=script.id,
    line=line,
    section=section,
    command='lua_rva_hook',
    arguments=U.array({
      module,
      string.format('0x%X',rva)
    }),
    ownership='unverified',
    lifecycle='unverified',
    hook={
      kind='lua_rva_hook',
      module=module,
      rva=string.format('0x%X',rva),
      expected_bytes=expected and #expected or U.null,
      original_bytes=original and #original or U.null,
      expected=expected or U.null,
      original=original or U.null,
      dynamic_aa=text:find('autoAssemble',1,true)~=nil,
      allocation=text:find('allocateMemory',1,true)~=nil
    }
  }

  U.warn(
    report,
    'LUA-RVA-HOOK',
    'Static module+RVA hook candidate detected lexically; runtime Lua was not executed.',
    script.id,
    line
  )
end

local scopes={
  aobscan='process',
  aobscanmodule='module'
}

local counts={
  aobscan=2,
  aobscanmodule=3
}

-- Deliberately narrow: no quoted names, expressions, macros or numeric addresses.
local function dependency(report,script,row,section,command,name,kind,relation)
  if not name or not name:match('^[A-Za-z_][A-Za-z0-9_]*$') or name:match('^%x+$') then
    return
  end
  report.dependencies[#report.dependencies+1]={
    script_id=script.id,line=row.line,section=section,command=command,
    name=name,kind=kind,relation=relation,source='lexical',status='unverified'
  }
end

local function commandDependencies(report,script,row,section,cmd,args)
  local function add(name,kind,relation)
    dependency(report,script,row,section,cmd,name,kind,relation)
  end
  if scopes[cmd] and #args==counts[cmd] then
    add(args[1],'symbol','provides')
  elseif cmd=='define' and #args==2 then
    add(args[1],'symbol','provides')
    add(args[2],'symbol','requires')
  elseif cmd=='label' and #args==1 then
    add(args[1],'symbol','provides')
  elseif (cmd=='alloc' and (#args==2 or #args==3))
    or (cmd=='globalalloc' and #args==2) then
    add(args[1],'resource','provides')
    add(args[1],'symbol','provides')
    if args[3] then add(args[3],'symbol','requires') end
  elseif cmd=='registersymbol' or cmd=='unregistersymbol' then
    for _,name in ipairs(args) do
      add(name,'symbol','requires')
      if cmd=='registersymbol' then add(name,'registered_symbol','provides') end
    end
  elseif cmd=='dealloc' and #args==1 then
    add(args[1],'resource','requires')
  end
end

function M.inspect(script,report)
  report.dependencies=report.dependencies or U.array()
  local section,disable,disableContent='common',false,false
  local lines=M.lines(script.text)

  script.labels=U.array()
  script.defines={}
  script.dynamic=false

  local luaText,luaLine={},nil
  local luaSection=section

  local function flushLua()
    if luaLine then
      local text=table.concat(luaText,'\n')
      luaDependencies(text,script,report,luaLine,luaSection)

      local embedded={
        id=script.id..'-lua-'..luaLine,
        language='Lua',
        text=text,
        origin='embedded',
        parent_script_id=script.id,
        record_key=script.record_key,
        line=luaLine
      }

      report.scripts[#report.scripts+1]=embedded

      inspectLuaHook(
        text,
        script,
        report,
        luaLine,
        luaSection
      )

      luaText={}
      luaLine=nil
    end
  end

  for _,row in ipairs(lines) do
    local s=row.text

    if row.directive=='opaque' then
      flushLua()
      script.dynamic=true
      if row.note=='SECTION-INDETERMINATE' then section='unknown' end
      if section=='disable' then disableContent=true end
      U.warn(report,row.note,'Opaque source; conditional branches are not evaluated and no execution semantics are inferred.',script.id,row.line)
    elseif row.luaSection then
      flushLua()
      section=s:lower():sub(2,-2)
      if section=='disable' then disable=true end
      luaSection=section
      luaLine=row.line+1

    elseif row.directive=='lua' then
      flushLua()
      luaSection=section
      script.dynamic=true
      luaLine=row.line+1

      if section=='disable' then
        disableContent=true
      end

    elseif row.lua then
      if section=='disable' and U.trim(row.lua)~='' then disableContent=true end
      luaText[#luaText+1]=row.lua

    elseif row.directive=='asm' then
      flushLua()

    elseif s:upper()=='[ENABLE]' then
      section='enable'

    elseif s:upper()=='[DISABLE]' then
      section='disable'
      disable=true

    elseif s~='' then
      if section=='disable' then
        disableContent=true
      end

      local cmd,raw=s:match('^([%w_]+)%s*%((.*)%)%s*$')
      cmd=cmd and cmd:lower()
      local args=raw and M.arguments(raw)
      local opaqueCommand=s:lower():match('^([%w_]+)%s*%(')
      if opaqueCommand=='hook' or opaqueCommand=='unhook' or opaqueCommand=='hook5'
        or opaqueCommand=='aobscanfunction' or opaqueCommand=='aobscanregion' then
        script.dynamic=true
        U.warn(report,'OPAQUE-COMMAND','Post-source command '..opaqueCommand..' observed lexically; unsupported semantics.',script.id,row.line)
        cmd=nil;args=nil;s=''
      end
      if cmd then commandDependencies(report,script,row,section,cmd,args) end

      if scopes[cmd] then
        local id='aob-'..(#report.aobs+1)

        report.aobs[#report.aobs+1]={
          id=id,
          script_id=script.id,
          line=row.line,
          section=section,
          command=cmd,
          arguments=args,
          symbol=args[1],
          scope=scopes[cmd],
          pattern=args[#args],
          syntax_supported=#args==counts[cmd],
          status='not_scanned',
          match_count=U.null,
          uniqueness='unverified',
          cross_build_robustness='unverified',
          matches=U.array(),
          matches_truncated=false,
          hook_candidates=U.array(),
          source_applicability='lexical_only'
        }

      elseif cmd=='define' and #args==2 and section~='disable' then
        local key=args[1]:lower()

        if script.defines[key]~=nil then
          script.defines[key]=false
        else
          script.defines[key]=args[2]
        end

      elseif cmd=='alloc'
        or cmd=='globalalloc'
        or cmd=='dealloc'
        or cmd=='registersymbol'
        or cmd=='unregistersymbol'
      then
        report.resources[#report.resources+1]={
          script_id=script.id,
          line=row.line,
          section=section,
          command=cmd,
          arguments=args,
          ownership='unverified',
          lifecycle='unverified'
        }

        if cmd=='dealloc' then
          U.warn(
            report,
            'RESTORE-BEFORE-FREE',
            'Review full byte restoration and in-flight execution before free; lexical order is not proof.',
            script.id,
            row.line
          )
        end

        if (cmd=='dealloc' or cmd=='unregistersymbol')
          and (raw=='' or raw:find('*',1,true))
        then
          U.warn(
            report,
            'RESOURCE-OWNERSHIP',
            'Broad cleanup candidate; ownership is unverified.',
            script.id,
            row.line
          )
        end

      elseif cmd=='include'
        or cmd=='luacall'
        or s:find('{$',1,true)
      then
        script.dynamic=true
      end

      local label=s:match('^(.-):$')

      if label then
        dependency(report,script,row,section,'address_label',U.trim(label),'symbol','requires')
      end

      if label and section~='disable' then
        script.labels[#script.labels+1]={
          expression=U.trim(label),
          line=row.line
        }
      end
    end
  end

  flushLua()

  if disable and not disableContent then
    U.warn(
      report,
      'EMPTY-DISABLE',
      'Empty DISABLE may intentionally keep a persistent library installed.',
      script.id
    )
  end

  if script.dynamic then
    U.warn(
      report,
      'DYNAMIC-SOURCE',
      'Lua/includes/preprocessor may change AA. Literal scans are lexical observations, not compiled-script equivalence.',
      script.id
    )
  end
end

return M

end
factories['semantics'] = function(require, api)
-- Evidence metadata only: no CE API calls, capability detection or source execution.
local U=require('util')
local M={}
function M.profile(ce_version)
  local function note(id,version,feature)
    return {id=id,version=version,feature=feature,
      evidence_kind='release_note_evidence',evidence_ref='user-chronology/'..version,
      runtime_validation='not_performed'}
  end
  return {
    profile_version='1',profile_id='ce-public-ec45d5f-to-runtime-r1',
    source_profile={repository='https://github.com/cheat-engine/cheat-engine',
      commit='ec45d5f47f92a239ba0bf51ec5d04a7509c3fd37',
      version_label='7.5.1 public-source baseline',version_label_basis='research_context_not_binary_identity'},
    runtime_profile={declared_version=U.null,declared_version_basis='not_available',
      api_version=ce_version,file_version=U.null,binary_sha256=U.null},
    source_runtime_equivalence='unverified',
    known_post_source_changes=U.array({
      note('luacode-no-dll-injection','7.5.2','LuaCode no longer requires DLL injection.'),
      note('globalalloc-save','7.6.1','Globalalloc symbols are no longer saved in tables.'),
      note('aa-conditionals-aob','7.6.2','IFDEF/IFNDEF/ENDIF conditionals also apply to AOB scans.'),
      note('aa-hook-unhook','7.6.3','HOOK/UNHOOK commands introduced.'),
      note('aobscanex-executable-fix','7.7.1','Fix for AOBSCANEX not being restricted to executable memory.'),
      note('async-thread-ondestroy','7.7.1','OnDestroy for the asynchronous Memory Record thread.')
    })
  }
end
return M

end
factories['simplereport'] = function(require, api)
-- Markdown rendering of the diagnostic assessment.
-- Presentation only: it never adds conclusions that are not in the assessment.
local U=require('util')
local M={}

local LIMITS={problem=50,advisory=12,not_assessed=10,healthy=20}

local function clean(value,limit)
  if type(value)=='number' then return tostring(value) end
  if type(value)~='string' then return '' end
  local s=value:gsub('[\r\n\t]+',' '):gsub('%s+',' ')
  s=s:gsub('`',"'"):gsub('<','&lt;'):gsub('>','&gt;')
  limit=limit or 400
  if #s>limit then s=s:sub(1,limit-3)..'...' end
  return s
end

local function code(value,limit)
  return '`'..clean(value,limit or 160)..'`'
end

local function bullets(lines,items,indent)
  if #items==0 then return end
  for _,item in ipairs(items) do
    lines[#lines+1]=(indent or '')..'- '..clean(item,400)
  end
end

local function bySeverity(diagnostics)
  local map={}
  for _,d in ipairs(diagnostics) do map[d.id]=d end
  return map
end

local function orderedByRepairPath(assessment,outcome)
  local map=bySeverity(assessment.diagnostics)
  local list={}
  for _,step in ipairs(assessment.repair_path) do
    local d=map[step.diagnostic_id]
    if d and d.outcome==outcome then list[#list+1]=d end
  end
  return list
end

local function renderDiagnostic(lines,d,index)
  lines[#lines+1]=string.format('### %d. %s',index,clean(d.label,160))
  lines[#lines+1]=''
  lines[#lines+1]=clean(d.summary,300)
  lines[#lines+1]=''
  lines[#lines+1]=string.format('Status: %s | Category: %s | Rule: %s | Confidence: %s',
    clean(d.status),clean(d.category),clean(d.rule),clean(d.confidence))
  lines[#lines+1]=''
  if #d.evidence>0 then
    lines[#lines+1]='**Evidence**'
    lines[#lines+1]=''
    local items={}
    for _,e in ipairs(d.evidence) do
      if type(e)=='table' and type(e.description)=='string' then items[#items+1]=e.description end
    end
    bullets(lines,items)
    lines[#lines+1]=''
  end
  if #d.confidence_reason>0 then
    lines[#lines+1]='**Why this confidence:** '..clean(table.concat(d.confidence_reason,' '),500)
    lines[#lines+1]=''
  end
  if #d.likely_causes>0 then
    lines[#lines+1]='**Possible causes (not proven)**'
    lines[#lines+1]=''
    bullets(lines,d.likely_causes)
    lines[#lines+1]=''
  end
  if #d.suggested_next_steps>0 then
    lines[#lines+1]='**Suggested next steps**'
    lines[#lines+1]=''
    for i,step in ipairs(d.suggested_next_steps) do
      lines[#lines+1]=string.format('%d. %s',i,clean(step,400))
    end
    lines[#lines+1]=''
  end
  if #d.do_not_assume>0 then
    lines[#lines+1]='**Do not assume**'
    lines[#lines+1]=''
    bullets(lines,d.do_not_assume)
    lines[#lines+1]=''
  end
  if #d.limitations>0 then
    lines[#lines+1]='**Limitations**'
    lines[#lines+1]=''
    bullets(lines,d.limitations)
    lines[#lines+1]=''
  end
end

function M.render(assessment,report)
  assert(type(assessment)=='table','simple report requires an assessment')
  report=report or {}
  local lines={}
  lines[#lines+1]='# CESuite Simple Report'
  lines[#lines+1]=''
  lines[#lines+1]='Generated: '..clean(assessment.generated_at,40)
  lines[#lines+1]=''
  lines[#lines+1]='Analysis mode: '..code(assessment.mode or 'unknown',40)
  local scope=assessment.scope or {}
  local target
  if scope.attached then
    target=(type(scope.process_name)=='string' and scope.process_name or 'attached process')..' (pid '..tostring(scope.pid)..')'
  else
    target='no process attached'
  end
  lines[#lines+1]=''
  lines[#lines+1]='Target: '..clean(target,200)
  lines[#lines+1]=''
  lines[#lines+1]='This report explains the evidence CESuite collected. It does not modify the table, the target or any script.'
  lines[#lines+1]=''
  lines[#lines+1]='## What CESuite analyzed'
  lines[#lines+1]=''
  lines[#lines+1]='- Modules enumerated: '..tostring(scope.module_count or 0)
  lines[#lines+1]='- Scripts inventoried: '..tostring(scope.script_count or 0)
  lines[#lines+1]='- AOB records: '..tostring(scope.aob_count or 0)
  lines[#lines+1]='- Dependency occurrences: '..tostring(scope.dependency_occurrence_count or 0)
  lines[#lines+1]='- Static Lua candidates: '..tostring(scope.static_candidate_count or 0)
  lines[#lines+1]=''
  lines[#lines+1]='**'..clean(assessment.headline,300)..'**'
  lines[#lines+1]=''

  local healthy={}
  for _,d in ipairs(assessment.diagnostics) do
    if d.outcome=='healthy' then healthy[#healthy+1]=d end
  end
  lines[#lines+1]='## What looks OK'
  lines[#lines+1]=''
  if #healthy==0 then
    lines[#lines+1]='No passing runtime checks were recorded in this collection.'
  else
    for i,d in ipairs(healthy) do
      if i>LIMITS.healthy then
        lines[#lines+1]=string.format('- ... and %d more passing check(s); see the extensive report.',#healthy-LIMITS.healthy)
        break
      end
      lines[#lines+1]='- '..clean(d.label,120)..': '..clean(d.summary,240)
    end
  end
  lines[#lines+1]=''

  local problems=orderedByRepairPath(assessment,'problem')
  lines[#lines+1]='## Problems'
  lines[#lines+1]=''
  if #problems==0 then
    lines[#lines+1]='No problems were detected in the evidence collected.'
  else
    for i,d in ipairs(problems) do
      if i>LIMITS.problem then
        lines[#lines+1]=string.format('_... and %d more problem(s); see the extensive report._',#problems-LIMITS.problem)
        lines[#lines+1]=''
        break
      end
      renderDiagnostic(lines,d,i)
    end
  end

  local advisories=orderedByRepairPath(assessment,'advisory')
  if #advisories>0 then
    lines[#lines+1]='## Source-only and advisory findings'
    lines[#lines+1]=''
    lines[#lines+1]='These findings come from lexical or static analysis. They are **not** runtime-verified.'
    lines[#lines+1]=''
    for i,d in ipairs(advisories) do
      if i>LIMITS.advisory then
        lines[#lines+1]=string.format('- ... and %d more advisory finding(s); see the extensive report.',#advisories-LIMITS.advisory)
        break
      end
      lines[#lines+1]='### '..clean(d.label,160)
      lines[#lines+1]=''
      lines[#lines+1]=clean(d.summary,300)
      lines[#lines+1]=''
      lines[#lines+1]=string.format('Status: %s | Confidence: %s | Rule: %s',
        clean(d.status),clean(d.confidence),clean(d.rule))
      lines[#lines+1]=''
      if #d.evidence>0 then
        local items={}
        for _,e in ipairs(d.evidence) do
          if type(e)=='table' and type(e.description)=='string' then items[#items+1]=e.description end
        end
        bullets(lines,items)
        lines[#lines+1]=''
      end
      if #d.suggested_next_steps>0 then
        lines[#lines+1]='**Suggested next steps**'
        lines[#lines+1]=''
        for k,step in ipairs(d.suggested_next_steps) do
          lines[#lines+1]=string.format('%d. %s',k,clean(step,400))
        end
        lines[#lines+1]=''
      end
      if #d.do_not_assume>0 then
        lines[#lines+1]='**Do not assume**'
        lines[#lines+1]=''
        bullets(lines,d.do_not_assume)
        lines[#lines+1]=''
      end
    end
    lines[#lines+1]=''
  end

  local notAssessed={}
  for _,d in ipairs(assessment.diagnostics) do
    if d.outcome=='not_assessed' then notAssessed[#notAssessed+1]=d end
  end
  if #notAssessed>0 then
    lines[#lines+1]='## Not assessed'
    lines[#lines+1]=''
    for i,d in ipairs(notAssessed) do
      if i>LIMITS.not_assessed then
        lines[#lines+1]=string.format('- ... and %d more item(s); see the extensive report.',#notAssessed-LIMITS.not_assessed)
        break
      end
      lines[#lines+1]='- '..clean(d.label,120)..': '..clean(d.summary,240)..' ('..clean(d.confidence)..' confidence)'
    end
    lines[#lines+1]=''
  end

  lines[#lines+1]='## Suggested Repair Path'
  lines[#lines+1]=''
  if #assessment.repair_path==0 then
    lines[#lines+1]='No repair step is suggested from the available evidence.'
  else
    lines[#lines+1]='Review in this order. Priority is fixed and does not depend on AI judgement.'
    lines[#lines+1]=''
    for _,step in ipairs(assessment.repair_path) do
      lines[#lines+1]=string.format('%d. %s',step.order,clean(step.action,300))
    end
  end
  lines[#lines+1]=''

  lines[#lines+1]='## How to read this report'
  lines[#lines+1]=''
  lines[#lines+1]='- `observed` means the status comes from a runtime observation recorded in this collection.'
  lines[#lines+1]='- `candidate` means lexical or static evidence only; runtime validity is not established.'
  lines[#lines+1]='- `unknown` means the evidence was insufficient or the operation could not be completed.'
  lines[#lines+1]='- `unsupported` means the construct is outside the analysis CESuite supports.'
  lines[#lines+1]='- Confidence levels: `high` (direct runtime evidence), `medium` (runtime evidence with a stated caveat), `low` (lexical/static inference), `unknown` (insufficient evidence).'
  lines[#lines+1]='- The extensive JSON report contains the same assessment with structured evidence.'
  lines[#lines+1]=''
  lines[#lines+1]='CESuite recommends what to review. It never changes the table, patches memory or generates hooks.'
  lines[#lines+1]=''
  return table.concat(lines,'\n')
end

-- Returns true on success, or nil plus a message. I/O errors are reported to the
-- caller (Core.exportReports returns a status table) instead of throwing.
function M.write(text,path)
  if type(text)~='string' then return nil,'simple report text required' end
  if type(path)~='string' or path=='' then return nil,'simple report path required' end
  local f,err=io.open(path,'wb')
  if not f then return nil,err or ('cannot open '..path) end
  local ok,failure=f:write(text)
  local closed,closeError=f:close()
  if not ok then return nil,failure or 'write failed' end
  if not closed then return nil,closeError or 'close failed' end
  return true
end

M.LIMITS=LIMITS
return M

end
